<script setup>
import {ref,onMounted,computed} from 'vue';import {LayoutDashboard,ClipboardList,Layers3,Users,Settings,Bell,Plus,ArrowUpRight,TrendingUp,MoreHorizontal,Search,ChevronDown} from 'lucide-vue-next';import {api} from '../api/client';
const tab=ref('overview');const dashboard=ref({});const orders=ref([]);const filter=ref('全部');const search=ref('');const showCreate=ref(false);const statuses=['全部','进行中','待确认','待开始','已完成'];
const fallbackOrders=[{id:1001,project:'Nora Studio 品牌官网',client:'Nora Studio',service:'品牌官网焕新',amount:'¥8,800',status:'进行中',deadline:'2026-08-22',avatar:'NS'},{id:1002,project:'Atlas 招聘工作台',client:'Atlas HR',service:'产品体验设计',amount:'¥12,600',status:'待确认',deadline:'2026-08-30',avatar:'AH'},{id:1003,project:'Flowbase 落地页',client:'Flowbase',service:'增长落地页',amount:'¥4,500',status:'已完成',deadline:'2026-08-12',avatar:'FB'},{id:1004,project:'Lumen 数据看板',client:'Lumen Labs',service:'数据看板系统',amount:'¥18,000',status:'待开始',deadline:'2026-09-05',avatar:'LL'}];
onMounted(async()=>{dashboard.value=await api.dashboard()||{revenue:'¥46,800',revenueGrowth:'+18.6%',activeOrders:12,newLeads:28,completionRate:'96.4%',trend:[28,42,35,56,48,72,66,80,74,92,86,108]};const r=await api.orders();orders.value=r?.items||fallbackOrders});
const list=computed(()=>{const all=orders.value.length?orders.value:fallbackOrders;return all.filter(o=>(filter.value==='全部'||o.status===filter.value)&&(!search.value||o.project.includes(search.value)||o.client.includes(search.value))) });
function barHeight(v){return {height:(v/120*100)+'%'}}
</script>
<template><div class="admin-layout"><aside class="sidebar"><RouterLink class="brand" to="/"><span class="brand-mark">TF</span><span>TaskFlow<span class="brand-dot">.</span></span></RouterLink><div class="side-label">WORKSPACE</div><nav><button :class="{active:tab==='overview'}" @click="tab='overview'"><LayoutDashboard :size="18"/>总览</button><button :class="{active:tab==='orders'}" @click="tab='orders'"><ClipboardList :size="18"/>订单管理<span class="nav-count">12</span></button><button><Layers3 :size="18"/>服务目录</button><button><Users :size="18"/>客户与伙伴</button></nav><div class="sidebar-bottom"><button><Settings :size="18"/>设置</button><div class="user-mini"><span class="avatar">TF</span><div><strong>TaskFlow 管理员</strong><small>超级管理员</small></div><ChevronDown :size="14"/></div></div></aside><main class="admin-main"><header class="admin-header"><div><span class="kicker">WEDNESDAY, AUG 14, 2026</span><h1>{{tab==='overview'?'早上好，TaskFlow。':'订单管理'}}</h1></div><div class="header-tools"><button class="icon-btn"><Bell :size="19"/><i></i></button><button class="btn btn-dark" @click="showCreate=true"><Plus :size="17"/>新建订单</button></div></header><section v-if="tab==='overview'" class="dashboard-content"><div class="metric-grid"><div class="metric-card"><span>本月收入</span><strong>{{dashboard.revenue||'¥46,800'}}</strong><small class="positive"><TrendingUp :size="14"/> {{dashboard.revenueGrowth||'+18.6%'}} <em>较上月</em></small></div><div class="metric-card"><span>进行中订单</span><strong>{{dashboard.activeOrders||12}}</strong><small class="neutral">+3 <em>本周新增</em></small></div><div class="metric-card"><span>待跟进线索</span><strong>{{dashboard.newLeads||28}}</strong><small class="warning">需要关注 <em>本周</em></small></div><div class="metric-card"><span>交付满意度</span><strong>{{dashboard.completionRate||'96.4%'}}</strong><small class="positive">优秀 <em>近 30 天</em></small></div></div><div class="dashboard-grid"><section class="panel revenue-panel"><div class="panel-head"><div><span class="kicker">REVENUE / 2026</span><h2>收入趋势</h2></div><button class="select-btn">近 12 个月 <ChevronDown :size="14"/></button></div><div class="chart"><div class="chart-y"><span>¥12k</span><span>¥8k</span><span>¥4k</span><span>¥0</span></div><div class="bars"><div v-for="(v,i) in (dashboard.trend||[28,42,35,56,48,72,66,80,74,92,86,108])" :key="i" class="bar-col"><div class="bar" :style="barHeight(v)"></div><small>{{['Sep','Oct','Nov','Dec','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug'][i]}}</small></div></div></div></section><section class="panel activity-panel"><div class="panel-head"><div><span class="kicker">ACTIVITY</span><h2>最近动态</h2></div><button class="icon-btn"><MoreHorizontal :size="19"/></button></div><div class="activity-list"><div><span class="activity-icon mint">✓</span><p><strong>Nora Studio</strong> 确认了里程碑 02<small>12 分钟前</small></p></div><div><span class="activity-icon violet">↗</span><p><strong>Atlas HR</strong> 提交了新需求<small>1 小时前</small></p></div><div><span class="activity-icon coral">¥</span><p>收到一笔 <strong>¥4,500</strong> 的尾款<small>3 小时前</small></p></div><div><span class="activity-icon blue">✦</span><p><strong>林默</strong> 加入了伙伴网络<small>昨天</small></p></div></div><button class="view-all" @click="tab='orders'">查看全部动态 <ArrowUpRight :size="14"/></button></section></div><section class="panel orders-panel"><div class="panel-head"><div><span class="kicker">ORDERS / LIVE</span><h2>订单概览</h2></div><button class="text-link" @click="tab='orders'">查看全部 <ArrowUpRight :size="15"/></button></div><OrderTable :rows="list.slice(0,4)"/></section></section><section v-else class="dashboard-content"><section class="panel orders-panel full-panel"><div class="panel-head"><div><span class="kicker">ORDERS / {{list.length}}</span><h2>全部订单</h2></div><div class="table-tools"><div class="search-box"><Search :size="16"/><input v-model="search" placeholder="搜索订单"/></div><div class="category-pills compact"><button v-for="s in statuses" :key="s" :class="{active:filter===s}" @click="filter=s">{{s}}</button></div></div></div><OrderTable :rows="list"/></section></section></main><div class="modal-wrap" v-if="showCreate" @click.self="showCreate=false"><div class="modal"><button class="modal-close" @click="showCreate=false">×</button><span class="kicker">NEW ORDER</span><h2>新建订单</h2><p>快速录入一个来自线下或其他渠道的项目。</p><form @submit.prevent="showCreate=false"><input required placeholder="项目名称"/><input required placeholder="客户名称"/><select><option>选择服务类型</option><option>品牌官网焕新</option><option>产品体验设计</option><option>增长落地页</option></select><input placeholder="订单金额"/><button class="btn btn-dark full" type="submit">创建订单 <ArrowUpRight :size="16"/></button></form></div></div></div></template>
<script>const OrderTable={props:['rows'],components:{ArrowUpRight,MoreHorizontal},template:`<div class="table-wrap"><table><thead><tr><th>项目</th><th>客户</th><th>服务</th><th>金额</th><th>状态</th><th>截止日期</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><div class="project-cell"><span class="avatar" :class="'avatar-'+row.avatar">{{row.avatar}}</span><strong>{{row.project}}</strong></div></td><td>{{row.client}}</td><td><span class="service-label">{{row.service}}</span></td><td><strong>{{row.amount}}</strong></td><td><span class="status" :class="row.status">{{row.status}}</span></td><td>{{row.deadline}}</td><td><button class="icon-btn"><MoreHorizontal :size="18"/></button></td></tr></tbody></table></div>`};</script>
